input.newString:
import { toggleNotifications, getNotificationsPreference } from './actions';

export default async function Home() {
  const notificationsEnabled = await getNotificationsPreference();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications: {notificationsEnabled ? 'ON' : 'OFF'}</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn {notificationsEnabled ? 'OFF' : 'ON'} Notifications
        </button>
      </form>
    </main>
  );
}

